// Minimal endless side‑scroll runner
// Canvas with id="game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');

  // Resize canvas to fill its container
  const resize = () => {
    canvas.width = canvas.clientWidth;
    canvas.height = canvas.clientHeight;
  };
  resize();
  window.addEventListener('resize', resize);

  const GRAVITY = 0.6;
  const JUMP_VELOCITY = -12;
  const SPEED = 4; // world scroll speed

  const groundY = canvas.height * 0.8;

  const player = {
    x: 50,
    y: groundY,
    w: 20,
    h: 20,
    vy: 0,
    onGround: true,
    draw() {
      ctx.fillStyle = '#00f';
      ctx.fillRect(this.x, this.y - this.h, this.w, this.h);
    },
    update() {
      this.vy += GRAVITY;
      this.y += this.vy;
      if (this.y >= groundY) {
        this.y = groundY;
        this.vy = 0;
        this.onGround = true;
      } else {
        this.onGround = false;
      }
    },
  };

  // simple obstacle definition
  const obstacles = [];
  const spawnObstacle = () => {
    const width = 20 + Math.random() * 30;
    const height = 20 + Math.random() * 40;
    obstacles.push({ x: canvas.width + width, y: groundY, w: width, h: height });
  };
  // spawn every ~1.5‑2 seconds
  setInterval(spawnObstacle, 1600);

  // Input: space or click triggers jump
  const tryJump = () => {
    if (player.onGround) {
      player.vy = JUMP_VELOCITY;
      player.onGround = false;
    }
  };
  window.addEventListener('keydown', (e) => { if (e.code === 'Space') tryJump(); });
  canvas.addEventListener('click', tryJump);

  let running = true;
  const gameOver = () => {
    running = false;
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '48px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  };

  const checkCollision = (obj) => {
    return (
      player.x < obj.x + obj.w &&
      player.x + player.w > obj.x &&
      player.y - player.h < obj.y &&
      player.y > obj.y - obj.h
    );
  };

  function loop() {
    if (!running) return;
    // clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // ground line
    ctx.fillStyle = '#654321';
    ctx.fillRect(0, groundY, canvas.width, canvas.height - groundY);
    // update and draw player
    player.update();
    player.draw();
    // move obstacles
    ctx.fillStyle = '#f00';
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const o = obstacles[i];
      o.x -= SPEED;
      ctx.fillRect(o.x, o.y - o.h, o.w, o.h);
      if (checkCollision(o)) {
        gameOver();
        return;
      }
      // remove off‑screen
      if (o.x + o.w < 0) obstacles.splice(i, 1);
    }
    requestAnimationFrame(loop);
  }

  loop();
})();
